using BrewNest.Contracts.Sales;
using BrewNest.Modules.Sales.Application.Services;
using BrewNest.Modules.Sales.Infrastructure.Persistence;
using Microsoft.EntityFrameworkCore;

namespace BrewNest.UnitTests;

/// <summary>Verifies core Sales workflow and discount invariants.</summary>
public sealed class SalesServiceTests
{
    /// <summary>Dine-in orders cannot be created without a valid table.</summary>
    [Fact]public async Task DineInRequiresTable(){await using var db=Database();var result=await Service(db).CreateAsync(new(SalesOrderType.DineIn,null,null,"","","",""),new("cashier"),default);Assert.False(result.Succeeded);Assert.Contains("dining table",string.Join(' ',result.Errors),StringComparison.OrdinalIgnoreCase);}
    /// <summary>Delivery orders require contact and address information.</summary>
    [Fact]public async Task DeliveryRequiresCustomerContact(){await using var db=Database();var result=await Service(db).CreateAsync(new(SalesOrderType.Delivery,null,null,"Customer","","",""),new("cashier"),default);Assert.False(result.Succeeded);Assert.Contains("Delivery orders require",string.Join(' ',result.Errors));}
    /// <summary>Billing is blocked while any discount awaits manager approval.</summary>
    [Fact]public async Task PendingDiscountBlocksBilling(){await using var db=Database();var service=Service(db);var order=Value(await service.CreateAsync(new(SalesOrderType.Takeaway,null,null,"","","",""),new("cashier"),default),"create");order=Value(await service.AddLineAsync(order.Id,new(TestCatalog.MenuItem.Id,2m,"",order.Version),new("cashier"),default),"add line");order=Value(await service.ConfirmAsync(order.Id,new("confirmed",order.Version),new("cashier"),default),"confirm");order=Value(await service.RequestDiscountAsync(order.Id,new(10m,"student promotion",order.Version),new("cashier"),default),"request discount");var billed=await service.BillAsync(order.Id,new("bill",order.Version),new("cashier"),default);Assert.False(billed.Succeeded);Assert.Contains("awaiting approval",string.Join(' ',billed.Errors));}
    /// <summary>Approved discounts produce the expected final immutable bill values.</summary>
    [Fact]public async Task ApprovedDiscountCalculatesBill(){await using var db=Database();var service=Service(db);var order=Value(await service.CreateAsync(new(SalesOrderType.Takeaway,null,null,"","","",""),new("cashier"),default));order=Value(await service.AddLineAsync(order.Id,new(TestCatalog.MenuItem.Id,2m,"",order.Version),new("cashier"),default));order=Value(await service.RequestDiscountAsync(order.Id,new(10m,"manager promotion",order.Version),new("cashier"),default));var discount=Assert.Single(order.Discounts);order=Value(await service.DecideDiscountAsync(order.Id,discount.Id,new(true,"approved",order.Version,discount.Version),new("manager"),default));order=Value(await service.ConfirmAsync(order.Id,new("confirmed",order.Version),new("cashier"),default));order=Value(await service.BillAsync(order.Id,new("final",order.Version),new("cashier"),default));Assert.NotNull(order.Bill);Assert.Equal(1000m,order.Bill.GrossAmount);Assert.Equal(100m,order.Bill.DiscountAmount);Assert.Equal(900m,order.Bill.NetAmount);}
    /// <summary>Adding an item after approval invalidates the approved discount.</summary>
    [Fact]public async Task AdditionalItemCancelsApprovedDiscount(){await using var db=Database();var service=Service(db);var order=Value(await service.CreateAsync(new(SalesOrderType.Takeaway,null,null,"","","",""),new("cashier"),default));order=Value(await service.AddLineAsync(order.Id,new(TestCatalog.MenuItem.Id,1m,"",order.Version),new("cashier"),default));order=Value(await service.RequestDiscountAsync(order.Id,new(5m,"promotion",order.Version),new("cashier"),default));var discount=Assert.Single(order.Discounts);order=Value(await service.DecideDiscountAsync(order.Id,discount.Id,new(true,"approved",order.Version,discount.Version),new("manager"),default));order=Value(await service.AddLineAsync(order.Id,new(TestCatalog.MenuItem.Id,1m,"additional",order.Version),new("cashier"),default));Assert.Equal(SalesDiscountStatus.Cancelled,Assert.Single(order.Discounts).Status);Assert.Equal(0m,order.DiscountAmount);}
    private static SalesDbContext Database()=>new(new DbContextOptionsBuilder<SalesDbContext>().UseInMemoryDatabase($"sales-{Guid.NewGuid():N}").Options);private static SalesService Service(SalesDbContext db)=>new(db,new TestCatalog(),new TestNumbers(),new FixedTime());private static T Value<T>(SalesResult<T> result,string stage="operation"){Assert.True(result.Succeeded,$"{stage}: {string.Join(' ',result.Errors)}");return Assert.IsType<T>(result.Value);}
    private sealed class TestCatalog:ISalesCatalogPort{public static SalesMenuItemReference MenuItem{get;}=new(Guid.Parse("aaaaaaaa-0000-0000-0000-000000000001"),"COF","Coffee",500m);public Task<SalesReferenceDataResponse> GetReferencesAsync(CancellationToken cancellationToken)=>Task.FromResult(new SalesReferenceDataResponse([MenuItem],[],[new(Guid.Parse("bbbbbbbb-0000-0000-0000-000000000001"),"T1","Table",4,"Main")]));public Task<SalesMenuItemReference?> GetMenuItemAsync(Guid id,CancellationToken cancellationToken)=>Task.FromResult(id==MenuItem.Id?MenuItem:null);public Task<bool> IsCustomerActiveAsync(Guid id,CancellationToken cancellationToken)=>Task.FromResult(true);public Task<bool> IsDiningTableActiveAsync(Guid id,CancellationToken cancellationToken)=>Task.FromResult(true);}
    private sealed class TestNumbers:ISalesDocumentNumberPort{public string NextOrderNumber()=>"SO-TEST";public string NextBillNumber()=>"INV-TEST";}private sealed class FixedTime:TimeProvider{public override DateTimeOffset GetUtcNow()=>new(2026,9,23,12,0,0,TimeSpan.Zero);}
}
